urlset:
{% for p in page.pages -%}
  {%- if p.permalink and not p.sitemap.disable -%}

  {{ p.permalink }}
  {%- if p.lastmod %}
  {{ p.lastmod | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
  {%- endif %}
  {%- if p.sitemap.change_freq %}
  {{ p.sitemap.change_freq }}
  {%- endif %}
  {%- if p.sitemap.priority >= 0 %}
  {{ p.sitemap.priority }}
  {%- endif %}
  {%- if p.is_translated %}
    {%- set full = p | deref %}
    {%- for t in full.translations %}

    {%- endfor %}

  {%- endif %}

  {%- endif -%}
{%- endfor %}
